        ctx.act2({ actors: P, cat: 'solo', fx: function () { P.forEach(function (c) { ctx.stress(c, 10); }); }, text: t, why: n.label + 'の配信（' + (r.truth ? '本当の情報' : 'デマ') + '）と、その騒音', mag: 22 });
